<?php
declare(strict_types=1);
namespace Nexus\Features\Inventario\Application;
use Nexus\Features\Inventario\Domain\InventarioRepository;use Nexus\Shared\Domain\ValueObject\Cedula;use Nexus\Shared\DomainException;
final class InventarioService
{
    private InventarioRepository $repo;public function __construct(InventarioRepository $r){$this->repo=$r;}
    public function equipos():array{return array_map(function($f){return ['id'=>(string)$f['id_equipo'],'nombre'=>$f['nombre_equipo'],'tipo'=>$f['categoria_equipo']?:'otro','tipoEtiqueta'=>$f['categoria_equipo']?:'Otro','icono'=>'package','seccionId'=>(string)$f['id_ubicacion'],'seccion'=>$f['seccion_inventario'],'fechaAlta'=>$f['fecha_agregado'],'actualizado'=>'hoy','estaActivo'=>(int)$f['esta_activo']===1,'estado'=>$f['estado_equipo']==='Baja'?'Baja':($f['estado_equipo']==='Mantenimiento'?'Mantenimiento':'Activo'),'observaciones'=>$f['descripcion']??'','marca'=>$f['marca_equipo']??'','cantidad'=>(int)$f['cantidad_del_equipo'],'cantidadDisponible'=>(int)($f['cantidad_disponible']??$f['cantidad_del_equipo'])];},$this->repo->listarEquipos());}
    public function altaEquipo(array $d,Cedula $autor):int{$this->validarEquipo($d,false);if(!$this->repo->ubicacionExiste($d['seccionId']))throw new DomainException('No existe la sección indicada.',404);$d['activo']=$d['estado']==='Baja'?0:1;$d['estadoBase']=$d['estado']==='Mantenimiento'?'Mantenimiento':($d['estado']==='Baja'?'Baja':'Disponible');return $this->repo->crearEquipo($d,$autor);}
    public function editarEquipo(int $id,array $d,Cedula $autor):void{$this->validarEquipo($d,true);if(!in_array($d['estado'],['Disponible','Mantenimiento'],true))throw new DomainException('El estado del equipo no es válido.');if(!$this->repo->ubicacionExiste($d['seccionId'],true))throw new DomainException('No existe la sección activa indicada.',404);if(!$this->repo->editarEquipo($id,$d,$autor))throw new DomainException('No existe el equipo activo indicado.',404);}
    public function trasladarEquipo(int $id,int $destino,Cedula $autor):array{if(!$this->repo->ubicacionExiste($destino))throw new DomainException('No existe la sección indicada.',404);$r=$this->repo->trasladarEquipo($id,$destino,$autor);if($r===null)throw new DomainException('No existe el equipo indicado.',404);return ['ok'=>true,'sinCambios'=>$r===false];}
    public function bajaEquipo(int $id,Cedula $autor):array{$r=$this->repo->bajaEquipo($id,$autor);if($r===null)throw new DomainException('No existe el equipo indicado.',404);return ['ok'=>true,'sinCambios'=>$r===false];}
    public function ubicaciones():array{$this->exigirEsquema();return array_map(fn($f)=>['id'=>(string)$f['id_ubicacion'],'nombre'=>$f['seccion_inventario'],'icono'=>'building-2','actualizado'=>'hoy','cantidadEquipos'=>(int)$f['cantidad_equipos']],$this->repo->listarUbicaciones());}
    public function altaUbicacion(string $n,Cedula $autor):int{$this->exigirEsquema();if($n==='')throw new DomainException('El nombre de la ubicación es obligatorio.');return $this->repo->crearUbicacion($n,$autor);}
    public function renombrarUbicacion(int $id,string $n,Cedula $autor):void{$this->exigirEsquema();if($n==='')throw new DomainException('El nombre de la ubicación es obligatorio.');if(!$this->repo->renombrarUbicacion($id,$n,$autor))throw new DomainException('No existe la sección activa o no hubo cambios.',404);}
    public function bajaUbicacion(int $id,?int $destino,Cedula $autor):array{$this->exigirEsquema();if($destino===$id)throw new DomainException('La sección destino debe ser distinta a la sección eliminada.');$r=$this->repo->bajaUbicacion($id,$destino,$autor);if($r===null)throw new DomainException('No existe la ubicación indicada.',404);return ['ok'=>true,'sinCambios'=>!empty($r['sinCambios']),'equiposTrasladados'=>$r['cantidad']??0,'seccionDestinoId'=>isset($r['destino'])?(string)$r['destino']:''];}
    private function exigirEsquema():void{if(!$this->repo->esquemaUbicacionesActualizado())throw new DomainException('La base de datos no está actualizada. Importa database.sql.',500);}
    private function validarEquipo(array $d,bool $edicion):void{if($d['nombre']===''||$d['tipo']==='')throw new DomainException('Nombre y categoría son obligatorios.');if(!$edicion&&(!is_int($d['cantidad'])||$d['cantidad']<1))throw new DomainException('La cantidad del equipo debe ser un entero positivo.');}
}
